@page {
    size: A4;
    margin: 0;
}

/* Hard reset */
html, body {
    margin: 0;
    padding: 0;
    width: 210mm;
    height: 297mm;
    -webkit-print-color-adjust: exact;
    print-color-adjust: exact;
}

/* Frappe wrapper reset */
.print-format {
    margin: 0;
    padding: 0;
}

/* A4 page container */
.page {
    position: relative;
    width: 210mm;
    height: 297mm;
    overflow: hidden;
    page-break-after: always;
}

/* Background letterhead – LOCKED to A4 */
.page .bg {
    position: absolute;
    top: 0;
    left: 0;
    width: 210mm;
    height: 297mm;
    z-index: 0;
}

/* Content layer */
.page .content {
    position: absolute;
    top: 48mm;          /* Header height */
    left: 0;
    right: 0;
    padding-left: 20mm;
    padding-right: 20mm;
    padding-bottom: 30mm; /* Footer safe area */
    z-index: 1;

    box-sizing: border-box;
    font-family: "Times New Roman", serif;
    font-size: 15px;
    line-height: 1.4;
    text-align: justify;
}

/* Title */
.content h2 {
    margin: 0 0 28px 0;
    font-size: 20px;
    font-weight: bold;
    text-align: center;
    letter-spacing: 0.4px;
}

/* Paragraph base */
.content p {
    margin: 0 0 14px 0;     /* natural paragraph gap */
    font-size: 16px;
    line-height: 1.55;     /* restores breathing space */
    text-indent: 30px;
}

/* Details block (employee info) */
.details {
    margin-bottom: 26px;
}

.details p {
    margin: 0 0 8px 0;
    text-indent: 0;
}

/* Right-aligned date */
.content p[style*="text-align:right"] {
    margin-bottom: 20px;
    text-indent: 0;
}

/* Signature */
.signature {
    margin-top: 36px;
    font-size: 15px;
    font-weight: bold;
    text-indent: 0;
}
/* Force rich, solid print text */
.page .content,
.page .content p,
.page .content h2 {
    color: #000000 !important;   /* true black */
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
    text-rendering: geometricPrecision;
}

