html, body {
    margin: 0;
    padding: 0;
    -webkit-print-color-adjust: exact;
    print-color-adjust: exact;
}

.print-format {
    margin: 0;
    padding: 0;
}

/* A4 page — normal flow, background image locked behind */
.page {
    position: relative;
    width: 210mm;
    min-height: 297mm;
    box-sizing: border-box;
    /* top padding = letterhead header height (~45mm) */
    padding-top: 46mm;
    /* bottom padding = letterhead footer height — keeps content above footer (~42mm) */
    padding-bottom: 44mm;
    padding-left: 22mm;
    padding-right: 22mm;
}

/* Background letterhead image — locked to A4, never moves */
.page .bg {
    position: absolute;
    top: 0;
    left: 0;
    width: 210mm;
    height: 297mm;
    z-index: 0;
    display: block;
}

/* Content sits in normal flow on top of background */
.page .content {
    position: relative;
    z-index: 1;
    box-sizing: border-box;
    font-family: "Times New Roman", serif;
    font-size: 14px;
    line-height: 1.45;
    text-align: justify;
    word-wrap: break-word;
    overflow-wrap: break-word;
    white-space: normal;
    color: #000000;
}

/* Title */
.content h2 {
    margin: 0 0 16px 0;
    font-size: 18px;
    font-weight: bold;
    text-align: center;
    letter-spacing: 0.4px;
}

/* Paragraph base */
.content p {
    margin: 0 0 10px 0;
    font-size: 14px;
    line-height: 1.5;
    text-indent: 28px;
}

/* Details block (employee info) */
.details {
    margin-bottom: 16px;
}

.details p {
    margin: 0 0 5px 0;
    text-indent: 0;
    font-size: 14px;
}

/* Signature */
.signature {
    margin-top: 24px;
    font-size: 14px;
    font-weight: bold;
}

